"""Reproduce and refine the open label-versus-running-text recurrence audit."""
import argparse
from collections import Counter, defaultdict
from dataclasses import dataclass
from functools import lru_cache
from hashlib import sha256
import json
from pathlib import Path
from random import Random
import re
from statistics import mean

from vs import ivtff, split

EDITIONS={'zl':'ZL3b-n.txt','it':'IT2a-n.txt','rf':'RF1b-e.txt','gc':'GC2a-n.txt'}
SEEDS=(408,910031)
SHUFFLES=999
NORMAL_SUBTYPES={'0','1'}

@dataclass
class Page:
    id: str
    section: str | None
    labels: tuple
    reference: tuple
    ordinary: tuple = ()
    last_id: str | None = None

def leaf(id_):
    return re.match(r'f\d+',id_)[0]

@lru_cache(None)
def glyphs(word, convention):
    return tuple(word) if convention=='raw' else tuple(ivtff.segment(word,'eva-basic'))

def words(lines):
    return tuple(w for line in lines for w in line.words if w and not ivtff.uncertain(w))

def eligible(token_set, convention):
    return tuple(w for w in token_set if len(glyphs(w,convention))>=3)

def legacy(pages, convention):
    out=[]
    for page in pages:
        query=eligible(words(l for l in page.lines if l.unit=='L'),convention)
        ref=words(l for l in page.lines if l.unit!='L')
        if len(query)>=3 and len(ref)>=30:
            out.append(Page(page.id,page.section,query,ref))
    return out

def basic_pair(pages, convention):
    out=[]
    for page in pages:
        paragraphs=[l for l in page.lines if l.unit=='P' and l.subtype in NORMAL_SUBTYPES and l.words]
        label=eligible(words(l for l in page.lines if l.unit=='L'),convention)
        if len(paragraphs)<6 or len(label)<3:
            continue
        last=paragraphs[-1]
        trial=eligible(words([last]),convention)
        if not trial:
            continue
        ref=words(l for l in page.lines if l.unit!='L' and l.id!=last.id)
        if len(ref)>=30:
            out.append(Page(page.id,page.section,label,ref,trial,last.id))
    return out

def groups(pages):
    sec=defaultdict(list)
    for k,p in enumerate(pages):
        sec[p.section].append(k)
    return list(sec.values())

def matched_weights(lt,rt, key):
    by_cell=[defaultdict(list),defaultdict(list)]
    for items,words_ in zip(by_cell,(lt,rt)):
        for w in words_:
            items[key(w)].append(w)
    weighted=[]
    for side in range(2):
        response=Counter()
        mine,other=by_cell[side],by_cell[1-side]
        for k,patterns in mine.items():
            n=min(len(patterns),len(other.get(k,())))
            if n:
                weight=n/len(patterns)
                for w in patterns:
                    response[w]+=weight
        weighted.append(response)
    assert abs(weighted[0].total()-weighted[1].total())<1e-8
    return weighted

def reference_frequencies(all_pages, pairs):
    period=defaultdict(Counter)
    by_leaf=defaultdict(Counter)
    reserved={p.id:p.last_id for p in pairs}
    for p in all_pages:
        content=words(l for l in p.lines if l.unit!='L' and l.id!=reserved.get(p.id))
        period[p.section].update(content)
        by_leaf[p.section,leaf(p.id)].update(content)
    return period,by_leaf

def cell_freq(n, scheme):
    if scheme=='exact' or n<=8:
        return n,0
    return n.bit_length(),1

def page_deals(bins, amount, seed, forced=False):
    rng=Random(seed)
    length=sum(map(len,bins))
    for _ in range(amount):
        perm=list(range(length))
        for group in bins:
            if len(group)==1:
                continue
            values=group[:]
            while True:
                rng.shuffle(values)
                if not forced or all(a!=b for a,b in zip(group,values)):
                    break
            for a,b in zip(group,values):
                perm[a]=b
        yield perm

def cross_refs(rows,bins):
    cross=[]
    for group in bins:
        for i in group:
            peers=[j for j in group if i!=j]
            cross.append((i,mean(rows[i][j] for j in peers) if peers else None))
    return dict(cross)

def right_tail(draws,obs):
    return (1+sum(x>=obs-1e-12 for x in draws))/(1+len(draws))

def tail_table(draws,obs):
    return dict(mean=mean(draws),p=right_tail(draws,obs),permutations=len(draws),
                experimental_95=sorted(draws)[int(.95*len(draws))])

def words_matrix(queries, refs, test):
    return [[sum(wt for q,wt in weights.items() if test(j,q))
             for j in range(len(refs))] for weights in queries]

def fast_exact(refs):
    return lambda j,w:w in refs[j]

def edits1(refs,convention):
    originals=[]
    deletions=[]
    replaced=[]
    for page in refs:
        original={glyphs(w,convention) for w in page}
        originals.append(original)
        deleted=set()
        mask=set()
        for word in original:
            for i in range(len(word)):
                removed=word[:i]+word[i+1:]
                deleted.add(removed)
                mask.add((i,removed))
        deletions.append(deleted)
        replaced.append(mask)
    def hit(j,w):
        target=glyphs(w,convention)
        if target in originals[j] or target in deletions[j]:
            return True
        for i in range(len(target)):
            deleted=target[:i]+target[i+1:]
            if deleted in originals[j] or (i,deleted) in replaced[j]:
                return True
        return False
    return hit

def one_arm(pages, convention, near=False):
    if not pages:
        return None
    bins=groups(pages)
    refs=[set(p.reference) for p in pages]
    bags=[Counter(p.labels) for p in pages]
    n=sum(z.total() for z in bags)
    f=edits1(refs,convention) if near else fast_exact(refs)
    mat=words_matrix(bags,refs,f)
    observed=sum(m[i] for i,m in enumerate(mat))/n
    total=199 if near else SHUFFLES
    deals={}
    for seed in SEEDS:
        one={}
        for name,forcing in [('unrestricted',False),('forced_other',True)]:
            samples=[sum(row[j] for row,j in zip(mat,order))/n
                     for order in page_deals(bins,total,seed,forcing)]
            one[name]=tail_table(samples,observed)
        deals[str(seed)]=one
    exact_section_means={}
    for g in bins:
        key=pages[g[0]].section
        local=sum(bags[i].total() for i in g)
        diag=sum(mat[i][i] for i in g)/local
        fitted=sum(sum(mat[i][j] for j in g) for i in g)/(len(g)*local)
        other=sum(sum(mat[i][j] for j in g if j!=i) for i in g)/((len(g)-1)*local) if len(g)>1 else None
        if other is not None:
            assert abs(fitted-(diag/len(g)+other*(1-1/len(g))))<1e-13
        exact_section_means[key]=dict(pages=len(g),labels=local,own=diag,unrestricted=fitted,strict_cross=other)
    return dict(pages=len(pages),words=n,eligible_page_ids=[p.id for p in pages],observed=observed,deals=deals,
                by_section=exact_section_means)

def paired(pairs, source, convention, scheme):
    background,adjacent=reference_frequencies(source,pairs)
    kept=[]
    for p in pairs:
        total=background[p.section]
        leave_out=adjacent[p.section,leaf(p.id)]
        def key(w):
            return len(glyphs(w,convention)),cell_freq(total[w]-leave_out[w],scheme)
        equal=matched_weights(p.labels,p.ordinary,key)
        if equal[0]:
            kept.append((p,equal))
    category_count=Counter(p.section for p,_ in kept)
    kept=[(p,qs) for p,qs in kept if category_count[p.section]>1]
    base=dict(eligible_pages=len(pairs),eligible_labels=sum(len(p.labels) for p in pairs),
              eligible_ordinary=sum(len(p.ordinary) for p in pairs),
              section_eligible=Counter(p.section for p in pairs),
              paired_pages=len(kept),matched_by_page={p.id:m[0].total() for p,m in kept},
              removed_singleton_sections=[s for s,n in category_count.items() if n<2])
    if not kept:
        return base
    pages=[p for p,_ in kept]
    refs=[set(p.reference) for p in pages]
    bs=groups(pages)
    a=words_matrix([x[0] for _,x in kept],refs,fast_exact(refs))
    b=words_matrix([x[1] for _,x in kept],refs,fast_exact(refs))
    weight=sum(x[0].total() for _,x in kept)
    a_cross=cross_refs(a,bs)
    b_cross=cross_refs(b,bs)
    details={kind:dict(own=sum(m[i] for i,m in enumerate(rows))/weight,
                       cross=sum(cross.values())/weight)
             for kind,rows,cross in [('label',a,a_cross),('ordinary',b,b_cross)]}
    for rec in details.values():
        rec['excess']=rec['own']-rec['cross']
        rec['ratio']=rec['own']/rec['cross'] if rec['cross'] else None
    delta=details['label']['excess']-details['ordinary']['excess']
    obs=(details['label']['own'],details['ordinary']['own'])
    d0=obs[0]-obs[1]
    permutations={}
    for seed in SEEDS:
        pairs_score=[(sum(x[j] for x,j in zip(a,deal))/weight,sum(x[j] for x,j in zip(b,deal))/weight)
                     for deal in page_deals(bs,SHUFFLES,seed)]
        permutations[str(seed)]=dict(label=tail_table([x for x,y in pairs_score],obs[0]),
                                     ordinary=tail_table([y for x,y in pairs_score],obs[1]),
                                     label_minus_ordinary=tail_table([x-y for x,y in pairs_score],d0))
    block=defaultdict(lambda:[0.,0.])
    for i,(p,x) in enumerate(kept):
        loc=block[leaf(p.id)]
        loc[0]+=x[0].total()
        loc[1]+=a[i][i]-a_cross[i]-b[i][i]+b_cross[i]
    samples=[]
    rng=Random(909111)
    for _ in range(4999):
        sample=rng.choices(list(block.values()),k=len(block))
        samples.append(sum(v[1] for v in sample)/sum(v[0] for v in sample))
    samples.sort()
    lo,hi=samples[124],samples[4874]
    return dict(**base,paired_leaves=len(block),paired_sections=Counter(p.section for p in pages),
                matched_weight=weight,arm=details,delta=delta,leaf_bootstrap_95=[lo,hi],
                permutation=permutations)

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('raw',type=Path)
    cli=ap.parse_args()
    original={n:ivtff.parse(cli.raw/fn) for n,fn in EDITIONS.items()}
    public=set(split.select('practice',original['zl']))
    data=dict(source_sha256={n:sha256((cli.raw/f).read_bytes()).hexdigest() for n,f in EDITIONS.items()},scope={})
    for scope in ('exposed_public','practice_eval'):
        pages={n:[p for p in ps if scope=='exposed_public' or p.id in public] for n,ps in original.items()}
        pairing={n:basic_pair(ps,'raw' if n=='gc' else 'eva-basic') for n,ps in pages.items()}
        shared=set.intersection(*({(p.id,p.last_id) for p in ps} for ps in pairing.values()))
        output={}
        for n,ps in pages.items():
            conv='raw' if n=='gc' else 'eva-basic'
            legacy_raw=legacy(ps,'raw')
            legacy_canonical=legacy(ps,conv)
            other_fx=paired(pairing[n],original[n],conv,'fine')
            output[n]=dict(legacy_raw=one_arm(legacy_raw,'raw'),legacy_canonical=one_arm(legacy_canonical,conv),
                           legacy_near=one_arm(legacy_canonical,conv,True),
                           native_fine=other_fx,exact_frequency=paired(pairing[n],original[n],conv,'exact'),
                           matched_pages_fine=paired([p for p in pairing[n] if (p.id,p.last_id) in shared],
                                                     original[n],conv,'fine'))
        data['scope'][scope]=dict(shared_pages_and_last_locus=sorted(shared),readings=output)
    print(json.dumps(data,indent=2))

if __name__=='__main__':
    main()

scripts.section_sensitivity.py:
"""Relax exact matching from the source page to the source section."""
import argparse
from collections import Counter
import json
from math import fsum
from pathlib import Path

from vs import ivtff
from recurrence import (basic_pair, cell_freq, cross_refs, EDITIONS, fast_exact, glyphs, groups, leaf,
                        matched_weights, page_deals, reference_frequencies, tail_table,
                        words_matrix, SHUFFLES, SEEDS)

def evaluate(pages, corpus, convention, freq_scheme):
    sec=Counter(p.section for p in pages)
    retained=[p for p in pages if sec[p.section]>=2]
    if not retained:
        return None
    background,near=reference_frequencies(corpus,pages)
    query=[[],[]]
    cell_keys={}
    for i,page in enumerate(retained):
        counts=background[page.section]
        local=near[page.section,leaf(page.id)]
        for k,words in enumerate((page.labels,page.ordinary)):
            for w in words:
                position=(i,w)
                query[k].append(position)
                cell_keys[position]=(page.section,len(glyphs(w,convention)),
                                     cell_freq(counts[w]-local[w],freq_scheme))
    weights=matched_weights(*query,key=cell_keys.__getitem__)
    amount=weights[0].total()
    if not amount:
        return dict(pages=len(retained),matched=0)
    reference=[set(p.reference) for p in retained]
    bag_list=[]
    for side in weights:
        bags=[Counter() for _ in retained]
        for (i,w),f in side.items():
            bags[i][w]+=f
        bag_list.append(bags)
    bins=groups(retained)
    matrices=[words_matrix(bags,reference,fast_exact(reference)) for bags in bag_list]
    outcomes=[]
    for m in matrices:
        own=fsum(row[i] for i,row in enumerate(m))/amount
        cross=fsum(cross_refs(m,bins).values())/amount
        outcomes.append(dict(own=own,cross=cross,ratio=own/cross if cross else None,excess=own-cross))
    left,right=outcomes
    raw_diff=left['own']-right['own']
    results={}
    for seed in SEEDS:
        draws=[]
        for order in page_deals(bins,SHUFFLES,seed):
            a,b=(fsum(row[j] for row,j in zip(m,order))/amount for m in matrices)
            draws.append(a-b)
        results[str(seed)]=tail_table(draws,raw_diff)
    return dict(pages=len(retained),matched=amount,partition=Counter(p.section for p in retained),
                label=left,ordinary=right,delta=left['excess']-right['excess'],
                permuted_label_minus_ordinary=results)

def main():
    p=argparse.ArgumentParser()
    p.add_argument('raw',type=Path)
    x=p.parse_args()
    reports={}
    for name,filename in EDITIONS.items():
        normal='raw' if name=='gc' else 'eva-basic'
        text=ivtff.parse(x.raw/filename)
        ps=basic_pair(text,normal)
        reports[name]={s:evaluate(ps,text,normal,s) for s in ('fine','exact')}
    print(json.dumps(reports,indent=2))

if __name__=='__main__':
    main()

