"""Recompute pharmaceutical container vs herb-fragment label form."""
import argparse
from collections import Counter, defaultdict
from itertools import product
from json import dumps
from math import comb
from pathlib import Path
from statistics import mean

from vs import ivtff, split

FILES={'zl':'ZL3b-n.txt','it':'IT2a-n.txt','rf':'RF1b-e.txt'}
KINDS=('c','f')

def groups(pages, selected_ids, mode):
    output={}
    for p in pages:
        if p.section != 'P':
            continue
        keep=[]
        for line in p.lines:
            if line.unit!='L' or line.subtype not in KINDS or not line.words:
                continue
            if mode!='complete' and any(ivtff.uncertain(word) for word in line.words):
                continue
            if mode=='singleton' and len(line.words)!=1:
                continue
            if selected_ids is not None and line.id not in selected_ids:
                continue
            keep.append(line)
        if {line.subtype for line in keep}==set(KINDS):
            output[p.id]=keep
    return output

def measure(line, style):
    if style=='ending_lr':
        return int(line.words[-1][-1] in 'lr')
    return sum(len(ivtff.segment(word,style)) for word in line.words)

def selected_sum_counts(values, n):
    # Every assignment that marks n physical positions as containers has equal mass.
    counts=[Counter() for _ in range(n+1)]
    counts[0][0]=1
    for upto,value in enumerate(values,1):
        for k in range(min(n,upto),0,-1):
            for previous, ways in counts[k-1].items():
                counts[k][previous+value]+=ways
    assert counts[n].total()==comb(len(values),n)
    return counts[n]

def describe(by_page, style):
    observed=Counter()
    samples=defaultdict(list)
    null=Counter({0:1})
    for lines in by_page.values():
        y=[measure(line,style) for line in lines]
        is_container=[line.subtype=='c' for line in lines]
        for line,value in zip(lines,y):
            samples[line.subtype].append(value)
            observed[line.subtype]+=value
        local=selected_sum_counts(y,sum(is_container))
        next_null=Counter()
        for (s1,w1),(s2,w2) in product(null.items(),local.items()):
            next_null[s1+s2]+=w1*w2
        null=next_null
    if not samples:
        return None
    c,f=(samples[ty] for ty in KINDS)
    n=observed['c']
    total=null.total()
    higher=sum(w for k,w in null.items() if k>=n)
    lower=sum(w for k,w in null.items() if k<=n)
    expected=sum(k*w for k,w in null.items())
    abs_deviation=abs(n*total-expected)
    two_sided=sum(w for k,w in null.items() if abs(k*total-expected)>=abs_deviation)
    observed_difference=mean(c)-mean(f)
    # On a two-kind subset the global count is constant under permutations.
    # Compare pooled length/rate differences and also give the equal-page contrast.
    page_difference=[]
    for lines in by_page.values():
        here=defaultdict(list)
        for line in lines:
            here[line.subtype].append(measure(line,style))
        page_difference.append(mean(here['c'])-mean(here['f']))
    return dict(counts=[len(c),len(f)],means=[mean(c),mean(f)],observed_difference=observed_difference,
                equal_page_difference=mean(page_difference),folio_positive_differences=sum(k>0 for k in page_difference),
                p_greater=higher/total,p_lower=lower/total,p_abs_from_exact_mean=two_sided/total,
                assignments=total,statistic_support=len(null),
                observed_sum=n,permuted_mean=expected/total)

def main():
    cli=argparse.ArgumentParser()
    cli.add_argument('raw',type=Path)
    args=cli.parse_args()
    metrics=('eva-raw','eva-basic','eva-iin','ending_lr')
    out={}
    for space in ('split','joined'):
        pages={k:ivtff.parse(args.raw/v,uncertain_space=space) for k,v in FILES.items()}
        practice=set(split.select('practice',pages['zl']))
        selected_loci={k:{line.id for p in ps if p.section=='P' for line in p.lines
                          if line.unit=='L' and line.subtype in KINDS and line.words
                          and not any(ivtff.uncertain(word) for word in line.words)}
                       for k,ps in pages.items()}
        matched=set.intersection(*selected_loci.values())
        outcome={}
        for prefix,mask,mode in [('native_complete',None,'complete'),('native_certain',None,'certain'),
                                 ('native_singleton',None,'singleton'),('matched_certain',matched,'certain')]:
            for window in ('all_public','practice'):
                key=f'{prefix}/{window}'
                outcome[key]={}
                for k,ps in pages.items():
                    chosen=[p for p in ps if window=='all_public' or p.id in practice]
                    by=groups(chosen,mask,mode)
                    outcome[key][k]=dict(folios=list(by),metrics={m:describe(by,m) for m in metrics})
        out[space]=outcome
    print(dumps(out,indent=2))
if __name__=='__main__':
    main()

scripts.independent-jar/structure_sensitivity.py:
"""Check sensitivity to adjacent stacked label loci, plus stricter uncertainty."""
import argparse
from dataclasses import replace
import json
from pathlib import Path
import re

from audit import FILES, groups, describe
from vs import ivtff

# Conservative grouping sensitivity, not a mapping of every locus to an object.
# ZL comments explicitly associate .6/.7 on f99r (shared Petersen 72) and all
# three f102r2 loci below. The remaining pairs are plausible based on + position.
BUNDLES=(('f89r2.29','f89r2.30'),('f99r.6','f99r.7'),
         ('f102r2.13','f102r2.14','f102r2.15'),('f102v2.1','f102v2.2'))

def without_uncertain_alternatives(pages, raw_text):
    bad=set()
    for row in raw_text.splitlines():
        m=ivtff.LINE_RE.match(row)
        if m is None:
            continue
        leaf, n, _, unit, subtype, body=m.groups()
        if unit=='L' and subtype in ('c','f') and '[' in re.sub(r'<![^>]*>', '', body):
            bad.add(f'{leaf}.{int(n)}')
    return [replace(p,lines=[l for l in p.lines if l.id not in bad]) for p in pages],bad

def grouped(pages):
    starts={ids[0]:ids for ids in BUNDLES}
    avoids={x for ids in BUNDLES for x in ids[1:]}
    output=[]
    for p in pages:
        lookup={l.id:l for l in p.lines}
        lines=[]
        for ln in p.lines:
            if ln.id in avoids:
                continue
            if ln.id in starts:
                candidate=[lookup.get(i) for i in starts[ln.id]]
                if any(l is None or not l.words for l in candidate):
                    continue
                if any(l.unit!=ln.unit or l.subtype!=ln.subtype for l in candidate):
                    raise ValueError('Assigned bundle combines subtypes')
                words=[w for l in candidate for w in l.words]
                lines.append(replace(ln,words=words))
            else:
                lines.append(ln)
        output.append(replace(p,lines=lines))
    return output

def main():
    cl=argparse.ArgumentParser()
    cl.add_argument('raw',type=Path)
    v=cl.parse_args()
    out={}
    for name,path in FILES.items():
        p=v.raw/path
        parsed=ivtff.parse(p)
        strict,bad=without_uncertain_alternatives(parsed,p.read_text())
        out[name]={'dropped_alternatives':sorted(bad),'results':{}}
        variants={
            'merge_adjacent':grouped(parsed),
            'strict_alternative_filter':strict,
            'merged_and_strict':grouped(strict)}
        for policy,subset in variants.items():
            by=groups(subset,None,'certain')
            out[name]['results'][policy]={'folios':list(by),'eva-raw':describe(by,'eva-raw'),
                                          'eva-basic':describe(by,'eva-basic'),
                                          'final_lr':describe(by,'ending_lr')}
    print(json.dumps(out,indent=2))

if __name__ == '__main__':
    main()
